<script>document.addEventListener('click',function(event){const edit=event.target.closest('[data-guardian-edit]'),form=document.getElementById('guardianForm');if(edit){const d=JSON.parse(edit.dataset.guardianEdit);['id','name','relationship','cnic','mobile','email'].forEach(k=>{if(form.elements[k])form.elements[k].value=d[k]||''});Array.from(form.elements['students[]'].options).forEach(o=>o.selected=d.students.includes(o.value));form.querySelector('[data-guardian-form-title]').textContent='Edit Guardian';form.querySelector('[data-guardian-reset]').hidden=false;form.scrollIntoView({behavior:'smooth'})}if(event.target.closest('[data-guardian-reset]')){form.reset();form.elements.id.value='';form.querySelector('[data-guardian-form-title]').textContent='Add Guardian';event.target.hidden=true}})</script>
